package org.apache.commons.compress.utils;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.Closeable;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.fail;

public class IOUtils_skip_TriageGen2Test {







    @Test
    public void testSkip_PartialSkipPerCall() throws IOException {
        // Custom InputStream that simulates skip returning small chunks
        InputStream input = new InputStream() {
            private int pos = 0;
            private final byte[] data = {1, 2, 3, 4, 5};

            @Override
            public int read() throws IOException {
                if (pos >= data.length) return -1;
                return data[pos++];
            }

            @Override
            public long skip(long n) throws IOException {
                // Simulate a scenario where skip() doesn't skip the full requested amount at once
                // This forces the while loop to iterate multiple times
                long actualToSkip = Math.min(n, 1); 
                pos += (int) actualToSkip;
                return actualToSkip;
            }
        };

        long numToSkip = 3;
        long skipped = IOUtils.skip(input, numToSkip);

        assertEquals(3L, skipped);
    }




}

