import static org.junit.Assert.fail;

public class IOUtils_skip_TriageGen2Test {









    @Test
    public void testSkip_SkipReturnsZeroImmediately() throws IOException {
        // Custom InputStream that returns 0 on skip immediately
        InputStream input = new InputStream() {
            @Override
            public int read() throws IOException {
                return -1;
            }

            @Override
            public long skip(long n) throws IOException {
                return 0;
            }
        };

        long numToSkip = 5;
        long skipped = IOUtils.skip(input, numToSkip);

        assertEquals(0L, skipped);
    }


}

package org.apache.commons.compress.utils;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.Closeable;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.fail;

public class IOUtils_skip_TriageGen2Test {











    @Test
    public void testSkip_ThrowsIOException() throws IOException {
        InputStream input = new InputStream() {
            @Override
            public int read() throws IOException {
                return -1;
            }

            @Override
            public long skip(long n) throws IOException {
                throw new IOException("Simulated IO Error");
            }
        };

        try {
            IOUtils.skip(input, 5);
            fail("Should have thrown IOException");
        } catch (IOException e) {
            assertEquals("Simulated IO Error", e.getMessage());
        }
    }
}
